button.t-on-click:
() => {
                        env.services.action.doAction({
                            type: 'ir.actions.client',
                            tag: 'sale_ticket_pos',
                            target: 'new',
                            context: {'order_id': env.model.root.resId}
                        });
                    }

() => {
                        env.services.action.doAction({
                            type: 'object',
                            name: 'action_view_invoice',
                            resModel: 'sale.order',
                            resId: env.model.root.resId
                        });
                    }
